import React, { useEffect, useState, useCallback, useRef } from 'react';

const TOTAL_SECONDS = 15; // 3 banners × 5s each

export default function AdSplash({ onDone }) {
  const [banners, setBanners] = useState(null);
  const [index, setIndex] = useState(0);       // which banner (0,1,2)
  const [elapsed, setElapsed] = useState(0);   // total seconds elapsed (0→15)
  const [imgLoaded, setImgLoaded] = useState(false);
  const slotTimer = useRef(null);

  // ── Fetch the 3 banners for the current 12-hour slot ──────────
  const fetchBanners = useCallback(() => {
    fetch('http://localhost:5000/api/banners/current')
      .then((r) => r.json())
      .then((data) => {
        if (!data.banners || data.banners.length === 0) { onDone(); return; }
        setBanners(data.banners);
        setIndex(0);
        setElapsed(0);
        setImgLoaded(false);
        // Refresh banners when the 12-hour slot rolls over
        if (slotTimer.current) clearTimeout(slotTimer.current);
        if (data.slot_ends_in_ms > 0) {
          slotTimer.current = setTimeout(fetchBanners, data.slot_ends_in_ms);
        }
      })
      .catch(() => onDone()); // API down → let user in
  }, [onDone]);

  useEffect(() => {
    fetchBanners();
    return () => { if (slotTimer.current) clearTimeout(slotTimer.current); };
  }, [fetchBanners]);

  // ── Master 1-second tick ───────────────────────────────────────
  useEffect(() => {
    if (!banners) return;

    const tick = setInterval(() => {
      setElapsed((prev) => {
        const next = prev + 1;
        if (next >= TOTAL_SECONDS) {
          clearInterval(tick);
          onDone();
          return TOTAL_SECONDS;
        }
        // Switch banner every 5 seconds
        const newIndex = Math.floor(next / 5);
        setIndex((cur) => {
          if (newIndex !== cur) setImgLoaded(false);
          return newIndex < banners.length ? newIndex : cur;
        });
        return next;
      });
    }, 1000);

    return () => clearInterval(tick);
  }, [banners, onDone]);

  // ── Loading ────────────────────────────────────────────────────
  if (!banners) {
    return (
      <div style={s.overlay}>
        <div style={s.spinner} />
        <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>
      </div>
    );
  }

  const banner      = banners[index];
  const secInBanner = elapsed % 5;           // 0-4 within current banner
  const secLeft     = TOTAL_SECONDS - elapsed; // total seconds remaining

  // Arc for the circular countdown (full circle = 15s)
  const R = 28;
  const circ = 2 * Math.PI * R;
  const arcOffset = circ * (elapsed / TOTAL_SECONDS); // fills as time passes

  return (
    <div style={s.overlay}>
      <style>{`
        @keyframes spin { to { transform: rotate(360deg); } }
        @keyframes fadeIn { from { opacity:0 } to { opacity:1 } }
        @keyframes shimmer {
          0%   { background-position: -200% 0; }
          100% { background-position:  200% 0; }
        }
      `}</style>

      {/* ── Full-screen banner image ── */}
      {banner?.url && (
        <img
          key={banner.url}
          src={banner.url}
          alt=""
          onLoad={() => setImgLoaded(true)}
          style={{ ...s.bgImg, opacity: imgLoaded ? 1 : 0 }}
        />
      )}
      {!imgLoaded && <div style={s.shimmer} />}

      {/* Gradient overlays */}
      <div style={s.gradTop} />
      <div style={s.gradBottom} />

      {/* ── Top bar: logo + 3 segment dots ── */}
      <div style={s.topBar}>
        <span style={s.logo}>
          All <span style={{ color: '#f97316' }}>Things</span>
        </span>

        {/* 3 segment progress bars */}
        <div style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
          {banners.map((_, i) => {
            const done    = i < index;
            const current = i === index;
            const fill    = done ? '100%' : current ? `${(secInBanner / 5) * 100}%` : '0%';
            return (
              <div key={i} style={{ width: 56, height: 4, background: 'rgba(255,255,255,0.2)', borderRadius: 2, overflow: 'hidden' }}>
                <div style={{
                  height: '100%', width: fill,
                  background: done ? '#22c55e' : '#f97316',
                  borderRadius: 2,
                  transition: current ? 'width 1s linear' : 'none',
                }} />
              </div>
            );
          })}
        </div>
      </div>

      {/* ── Bottom bar ── */}
      <div style={s.bottomBar}>
        <div style={s.adBadge}>📢 Ad {index + 1} of {banners.length}</div>

        <div style={s.row}>
          {/* Circular countdown — counts down from 15 to 0 */}
          <div style={s.circleWrap}>
            <svg width={72} height={72} style={{ transform: 'rotate(-90deg)' }}>
              <circle cx={36} cy={36} r={R} fill="none" stroke="rgba(255,255,255,0.12)" strokeWidth={5} />
              <circle
                cx={36} cy={36} r={R}
                fill="none"
                stroke="#f97316"
                strokeWidth={5}
                strokeDasharray={circ}
                strokeDashoffset={arcOffset}
                strokeLinecap="round"
                style={{ transition: 'stroke-dashoffset 1s linear' }}
              />
            </svg>
            <span style={s.circleNum}>{secLeft}</span>
          </div>

          <div>
            <p style={s.headline}>Please watch the ad to continue</p>
            <p style={s.sub}>
              {secLeft > 0
                ? `${secLeft} second${secLeft !== 1 ? 's' : ''} remaining`
                : 'Opening…'}
            </p>
          </div>
        </div>

        {/* Single overall progress bar */}
        <div style={s.track}>
          <div style={{
            ...s.fill,
            width: `${(elapsed / TOTAL_SECONDS) * 100}%`,
            transition: 'width 1s linear',
          }} />
        </div>
        <p style={s.trackLabel}>{Math.round((elapsed / TOTAL_SECONDS) * 100)}% complete</p>
      </div>
    </div>
  );
}

const s = {
  overlay: { position: 'fixed', inset: 0, zIndex: 9999, background: '#000', overflow: 'hidden', userSelect: 'none' },
  bgImg: { position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover', transition: 'opacity 0.4s ease' },
  shimmer: {
    position: 'absolute', inset: 0,
    background: 'linear-gradient(110deg,#111 30%,#1c1c1c 50%,#111 70%)',
    backgroundSize: '200% 100%',
    animation: 'shimmer 1.4s infinite',
  },
  gradTop: { position: 'absolute', top: 0, left: 0, right: 0, height: 180, background: 'linear-gradient(to bottom,rgba(0,0,0,0.88),transparent)', pointerEvents: 'none' },
  gradBottom: { position: 'absolute', bottom: 0, left: 0, right: 0, height: 280, background: 'linear-gradient(to top,rgba(0,0,0,0.94),transparent)', pointerEvents: 'none' },
  topBar: { position: 'absolute', top: 0, left: 0, right: 0, padding: '20px 28px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' },
  logo: { fontSize: 22, fontWeight: 900, color: '#fff' },
  bottomBar: { position: 'absolute', bottom: 0, left: 0, right: 0, padding: '20px 28px 36px' },
  adBadge: { display: 'inline-block', background: 'rgba(249,115,22,0.18)', border: '1px solid rgba(249,115,22,0.4)', color: '#f97316', fontSize: 12, fontWeight: 700, padding: '5px 14px', borderRadius: 20, marginBottom: 16, letterSpacing: 0.5 },
  row: { display: 'flex', alignItems: 'center', gap: 18, marginBottom: 20 },
  circleWrap: { position: 'relative', width: 72, height: 72, flexShrink: 0 },
  circleNum: { position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 22, fontWeight: 900, color: '#fff' },
  headline: { color: '#fff', fontSize: 18, fontWeight: 700, margin: 0, textShadow: '0 2px 8px rgba(0,0,0,0.8)' },
  sub: { color: 'rgba(255,255,255,0.5)', fontSize: 13, margin: '4px 0 0' },
  track: { height: 5, background: 'rgba(255,255,255,0.15)', borderRadius: 3, overflow: 'hidden' },
  fill: { height: '100%', background: '#f97316', borderRadius: 3 },
  trackLabel: { color: 'rgba(255,255,255,0.35)', fontSize: 12, margin: '6px 0 0' },
  spinner: { position: 'absolute', top: '50%', left: '50%', transform: 'translate(-50%,-50%)', width: 40, height: 40, border: '3px solid rgba(249,115,22,0.3)', borderTopColor: '#f97316', borderRadius: '50%', animation: 'spin 0.8s linear infinite' },
};
